use std::collections::{BTreeMap, BTreeSet};

use egui::{Pos2, Vec2, ahash::HashMap};
use petgraph::graph::{NodeIndex, UnGraph};

use crate::{
    grid::GRID_SIZE,
    router_ng::{CoordX, CoordY, Point},
};

/// Layout for the routes generated by the router.  This layout
/// engine is separate from the router itself, which manages the
/// topological routing and finding the lowest cost path.  The layout
/// engine nudges the resulting routes to make them visually more
/// appealing, by chamfering corners and adding some spacing between
/// parallel routes.
#[derive(Debug, Clone, Default)]
pub struct LayoutBuilder {
    routes: Vec<Vec<Point>>,
}

const LANE_OFFSETS: [f32; 3] = [0.0, GRID_SIZE / 4.0, -GRID_SIZE / 4.0];

fn nudge_offset(lane: usize) -> f32 {
    LANE_OFFSETS[lane % LANE_OFFSETS.len()]
}

pub struct Layout {
    pub routes: BTreeMap<usize, Vec<Pos2>>,
}

impl LayoutBuilder {
    pub fn add_route(&mut self, route: Vec<Point>) {
        self.routes.push(route);
    }

    pub fn build(self) -> Layout {
        let mut x_coords = BTreeSet::new();
        let mut y_coords = BTreeSet::new();
        for route in &self.routes {
            for point in route {
                x_coords.insert(point.x);
                y_coords.insert(point.y);
            }
        }
        let mut node_points: BTreeSet<Point> = BTreeSet::new();
        x_coords.iter().for_each(|&x| {
            y_coords.iter().for_each(|&y| {
                node_points.insert(Point { x, y });
            });
        });
        let mut graph: UnGraph<Point, BTreeSet<usize>> = UnGraph::new_undirected();
        let node_map = node_points
            .iter()
            .map(|point| (*point, graph.add_node(*point)))
            .collect::<HashMap<_, _>>();
        for (route_ndx, route) in self.routes.iter().enumerate() {
            for window in route.windows(2) {
                let [p1, p2] = [window[0], window[1]];
                let points = iter_all_points(p1, p2, &x_coords, &y_coords);
                for pairs in points.windows(2) {
                    let [p1, p2] = [pairs[0], pairs[1]];
                    let n1 = node_map[&p1];
                    let n2 = node_map[&p2];
                    if let Some(edge) = graph.find_edge(n1, n2) {
                        graph.edge_weight_mut(edge).unwrap().insert(route_ndx);
                        continue;
                    }
                    graph.add_edge(
                        n1,
                        n2,
                        std::iter::once(route_ndx).collect::<BTreeSet<usize>>(),
                    );
                }
            }
        }
        let mut path_map: BTreeMap<usize, Vec<Pos2>> = BTreeMap::new();
        // Build out the paths for each route.
        for edge in graph.edge_indices() {
            let edge_weight = &graph[edge];
            let (n1, n2) = graph.edge_endpoints(edge).unwrap();
            let p1 = graph[n1];
            let p2 = graph[n2];
            for (lane, &route) in edge_weight.iter().enumerate() {
                let offset = nudge_offset(lane);
                let dir = if p1.x == p2.x {
                    Vec2::new(offset, 0.0)
                } else {
                    Vec2::new(0.0, offset)
                };
                let start: Pos2 = p1.into();
                let end: Pos2 = p2.into();
                path_map.entry(route).or_default().push(start + dir);
                path_map.entry(route).or_default().push(end + dir);
            }
        }
        Layout { routes: path_map }
    }
}

// Iterate over all points between start and end, where start and end are either
// horizontal or vertical.
fn iter_all_points(
    start: Point,
    end: Point,
    x_coords: &BTreeSet<CoordX>,
    y_coords: &BTreeSet<CoordY>,
) -> Vec<Point> {
    if start.x == end.x {
        let x = start.x;
        let y_start = start.y.min(end.y);
        let y_end = start.y.max(end.y);
        y_coords
            .range(y_start..=y_end)
            .map(|&y| Point { x, y })
            .collect()
    } else if start.y == end.y {
        let y = start.y;
        let x_start = start.x.min(end.x);
        let x_end = start.x.max(end.x);
        x_coords
            .range(x_start..=x_end)
            .map(|&x| Point { x, y })
            .collect()
    } else {
        panic!("start and end must be either horizontal or vertical");
    }
}
